new_records = []
records = re.split(r';(?=EPTV1\|)', cipher)
for record in records:
    if not record.startswith("EPTV1|"): continue
    parts = record.split('|', 7)
    if len(parts) < 7:
        new_records.append(record)
        continue
    
    method = parts[4]
    data = parts[6]
    
    new_data = data
    if method == "Array":
        vals = data.split(',')
        new_data = vals[0] if len(vals) > 0 else data
    elif method == "MinMaxInterval":
        vals = data.split(',')
        if len(vals) >= 4:
            new_data = f"{vals[0]},{vals[0]},1,1"
    
    parts[3] = "Variable"
    parts[6] = new_data
    
    new_records.append("|".join(parts))

out_cipher = ";".join(new_records)
print(out_cipher)
